css:
.button {
  margin: 0 10px;
  padding: 10px 30px;
  border: 5px solid #DF34DB;
  border-radius: 22px;
  font-size: 20px;
  color: #DF34DB;
  transition: transform 0.1s ease-in, all 0.08s ease-in;
  box-shadow: 0 5px 0 #dd04d9;
}

.button:hover {
  border-color: #ff00c8;
  box-shadow: 0 5px 0 #ff00c8;
}

.button:active {
  transform: translateY(5px);
  box-shadow: 0 0 0 #DF34DB;
}
